```turtle
@prefix fis:  <http://example.org/onto/securities#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities> a owl:Ontology ;
  rdfs:comment "An OWL ontology of securities, financial instruments and derivatives, modelled from a corpus on finance." .

#################################################################
# TOP-LEVEL CLASSES
#################################################################

fis:FinancialInstrument a owl:Class ;
  rdfs:label "Financial Instrument" ;
  rdfs:comment "A monetary contract between parties, that can be created, traded, modified and settled." .

fis:Security a owl:Class ;
  rdfs:label "Security" ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:comment "A tradable financial asset. Jurisdictions disagree on scope: the US treats any tradable financial asset (including derivatives) as a security, while the UK FCA Handbook restricts the term to equities, debentures, government/public securities, warrants and similar instruments, excluding most derivatives. This ontology follows the broader (US) treatment as the majority view and notes the UK restriction here." .

#################################################################
# BROAD SECURITY CATEGORIES (US tri-partite classification)
#################################################################

fis:DebtSecurity a owl:Class ;
  rdfs:label "Debt Security" ;
  rdfs:subClassOf fis:Security ;
  rdfs:comment "A security under which the holder is entitled to payment of principal and interest; may be called a debenture, bond, deposit, note or commercial paper depending on maturity and collateral." .

fis:EquitySecurity a owl:Class ;
  rdfs:label "Equity Security" ;
  rdfs:subClassOf fis:Security ;
  rdfs:comment "A share of equity interest in an entity such as the capital stock of a company, trust or partnership." .

fis:Derivative a owl:Class ;
  rdfs:label "Derivative" ;
  rdfs:subClassOf fis:Security ;
  rdfs:comment "A contract whose value depends on the performance of an underlier. Every derivative has: an underlier, a future act, a price, and a future date. Note: BIS classifies derivatives into three basic types (forwards, swaps, options), treating futures as a standardized exchange-traded forward; most other sources list forwards, futures, options and swaps as four sibling types. This ontology follows the majority four-way sibling treatment." ;
  rdfs:subClassOf [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:qualifiedCardinality 1 ; owl:onClass fis:Underlier ] ,
                  [ a owl:Restriction ; owl:onProperty fis:hasDeliveryDate ; owl:cardinality 1 ] ,
                  [ a owl:Restriction ; owl:onProperty fis:hasDeliveryPrice ; owl:cardinality 1 ] .

fis:HybridSecurity a owl:Class ;
  rdfs:label "Hybrid Security" ;
  rdfs:subClassOf fis:Security ;
  rdfs:comment "Combines characteristics of both debt and equity securities, e.g. preference shares, convertibles and equity warrants." .

owl:AllDisjointClasses [ owl:members ( fis:DebtSecurity fis:EquitySecurity fis:Derivative ) ] .

#################################################################
# ISSUERS
#################################################################

fis:Issuer a owl:Class ;
  rdfs:label "Issuer" ;
  rdfs:comment "The company or other entity issuing a security." .

fis:SovereignGovernment a owl:Class ; rdfs:subClassOf fis:Issuer ; rdfs:label "Sovereign Government" .
fis:LocalGovernment a owl:Class ; rdfs:subClassOf fis:Issuer ; rdfs:label "Local Government" ;
  rdfs:comment "A state, provincial, territorial, municipal or other governmental unit other than a sovereign government." .
fis:Corporation a owl:Class ; rdfs:subClassOf fis:Issuer ; rdfs:label "Corporation" .
fis:SupranationalOrganization a owl:Class ; rdfs:subClassOf fis:Issuer ; rdfs:label "Supranational Organization" ;
  rdfs:comment "An international organization such as the World Bank or IMF." .

owl:AllDisjointClasses [ owl:members ( fis:SovereignGovernment fis:LocalGovernment fis:Corporation fis:SupranationalOrganization ) ] .

#################################################################
# CREDIT RATING
#################################################################

fis:CreditRating a owl:Class ; rdfs:label "Credit Rating" .
fis:InvestmentGradeRating a owl:Class ; rdfs:subClassOf fis:CreditRating ;
  rdfs:comment "Bonds rated AAA, AA, A, and BBB." .
fis:HighYieldRating a owl:Class ; rdfs:subClassOf fis:CreditRating ;
  rdfs:comment "Bonds rated BB and below; also called non-investment grade, speculative grade, or junk." .

owl:AllDisjointClasses [ owl:members ( fis:InvestmentGradeRating fis:HighYieldRating ) ] .

#################################################################
# UNDERLIER (for derivatives)
#################################################################

fis:Underlier a owl:Class ;
  rdfs:label "Underlier" ;
  rdfs:comment "An item that can or must be bought or sold under a derivative contract: a commodity, a financial instrument, a price index, a currency, an interest rate, or a specified event." .

fis:Commodity a owl:Class ; rdfs:subClassOf fis:Underlier .
fis:Currency a owl:Class ; rdfs:subClassOf fis:Underlier .
fis:PriceIndex a owl:Class ; rdfs:subClassOf fis:Underlier .
fis:InterestRateBenchmark a owl:Class ; rdfs:subClassOf fis:Underlier .
fis:CreditEvent a owl:Class ; rdfs:subClassOf fis:Underlier ;
  rdfs:comment "An event such as a loan default that can serve as the underlier of a credit derivative." .
fis:FinancialInstrument rdfs:subClassOf fis:Underlier .

#################################################################
# FORMS OF SECURITY (ownership recording)
#################################################################

fis:BearerSecurity a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:label "Bearer Security" ;
  rdfs:comment "Entitles the holder to rights under the security merely by holding the security." .

fis:RegisteredSecurity a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:label "Registered Security" ;
  rdfs:comment "Entitles the holder to rights only if they appear on a security register maintained by the issuer or an intermediary." .

fis:BookEntrySecurity a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:label "Book-Entry Security" ;
  rdfs:comment "A non-certificated, dematerialized security existing only as an electronic record." .

owl:AllDisjointClasses [ owl:members ( fis:BearerSecurity fis:RegisteredSecurity fis:BookEntrySecurity ) ] .

#################################################################
# BOND AND DEBT-SECURITY SUBCLASSES
#################################################################

fis:Bond a owl:Class ;
  rdfs:subClassOf fis:DebtSecurity ;
  rdfs:label "Bond" ;
  rdfs:comment "A security under which the issuer owes the holder a debt, obliged to repay principal at maturity and usually to pay interest (coupon)." .

fis:Debenture a owl:Class ;
  rdfs:subClassOf fis:Bond ;
  rdfs:label "Debenture" ;
  rdfs:comment "An unsecured bond, having only a general claim on the issuer's assets and cash flows." .

fis:SecuredBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "A bond backed by specific pledged collateral." .

owl:AllDisjointClasses [ owl:members ( fis:SecuredBond fis:Debenture ) ] .

fis:SeniorBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Contractually senior to other unsecured debt; priority in bankruptcy." .
fis:SubordinatedBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Debt that is not senior; lower priority than senior bonds in liquidation." .

owl:AllDisjointClasses [ owl:members ( fis:SeniorBond fis:SubordinatedBond ) ] .

fis:MoneyMarketInstrument a owl:Class ;
  rdfs:subClassOf fis:DebtSecurity ;
  rdfs:label "Money Market Instrument" ;
  rdfs:comment "A short-term debt instrument with original maturity of one year or less, highly liquid, traded in the money market." .

fis:CommercialPaper a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MoneyMarketInstrument
      [ a owl:Restriction ; owl:onProperty fis:hasMaturityDate ; owl:someValuesFrom xsd:date ] ) ] ;
  rdfs:comment "An unsecured promissory note with a fixed maturity of usually less than 270 days." .

fis:CertificateOfDeposit a owl:Class ;
  rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "A time deposit sold by banks, thrift institutions, and credit unions with a specific fixed term." .

fis:RepurchaseAgreement a owl:Class ;
  rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "Short-term loans arranged by selling securities with an agreement to repurchase at a fixed price and date. NOTE: one passage lists this as a money market instrument while another states that repurchase agreements 'defy categorization' into the cash/derivative instrument matrix; modelled here per the majority placement as a money market instrument." .

fis:TreasuryBill a owl:Class ;
  rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "A short-term debt obligation of a national government, maturing in one year or less, typically sold at a discount." .

#################################################################
# BOND CLASSIFICATION BY ISSUER
#################################################################

fis:GovernmentBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ] ) ] ;
  rdfs:label "Government Bond" ;
  rdfs:comment "A bond issued by a sovereign national government; also called a treasury bond or sovereign bond." .

fis:MunicipalBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:LocalGovernment ] ) ] ;
  rdfs:label "Municipal Bond" ;
  rdfs:comment "A bond issued by a local authority or subdivision within a country." .

fis:SupranationalBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganization ] ) ] ;
  rdfs:label "Supranational Bond" ;
  rdfs:comment "A bond issued by a supranational organization such as the World Bank." .

fis:CorporateBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] ;
  rdfs:label "Corporate Bond" ;
  rdfs:comment "A bond issued by a corporation to raise financing." .

owl:AllDisjointClasses [ owl:members ( fis:GovernmentBond fis:MunicipalBond fis:SupranationalBond fis:CorporateBond ) ] .

fis:TreasuryBond a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
  rdfs:comment "US government bond with maturity of twenty to thirty years." .
fis:TreasuryNote a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
  rdfs:comment "US government bond with maturity of two to ten years." .

fis:GeneralObligationBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
  rdfs:comment "Principal and interest secured by the full faith and credit of the issuer and its taxing power." .
fis:RevenueBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
  rdfs:comment "Repayment guaranteed solely from revenues generated by a specified revenue-generating entity; typically non-recourse." .
fis:AssessmentBond a owl:Class ; rdfs:subClassOf fis:GeneralObligationBond ;
  rdfs:comment "Repayment based on property tax assessments of properties within the issuer's boundaries." .

owl:AllDisjointClasses [ owl:members ( fis:GeneralObligationBond fis:RevenueBond ) ] .

fis:HighYieldBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasCreditRating ; owl:someValuesFrom fis:HighYieldRating ] ) ] ;
  rdfs:label "High-Yield Bond" ;
  rdfs:comment "A bond rated below investment grade by credit rating agencies; also called a junk bond." .

#################################################################
# BOND CLASSIFICATION BY COUPON STRUCTURE
#################################################################

fis:FixedRateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Coupon remains constant throughout the life of the bond." .

fis:FloatingRateNote a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Coupon varies based on the movement of a money market reference rate such as SOFR." .

fis:ZeroCouponBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasCouponRate ; owl:hasValue "0.0"^^xsd:decimal ] ) ] ;
  rdfs:label "Zero-Coupon Bond" ;
  rdfs:comment "A bond in which the face value is repaid at maturity with no periodic interest payments; sold at a substantial discount." .

fis:InflationIndexedBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Principal and interest payments are indexed to the level of consumer prices." .

owl:AllDisjointClasses [ owl:members ( fis:FixedRateBond fis:FloatingRateNote fis:ZeroCouponBond ) ] .

#################################################################
# BOND OPTIONALITY AND CONVERTIBILITY
#################################################################

fis:CallableBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasEmbeddedOption ; owl:someValuesFrom fis:CallOption ] ) ] ;
  rdfs:label "Callable Bond" ;
  rdfs:comment "Gives the issuer the right to repay the bond before the maturity date." .

fis:PutableBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasEmbeddedOption ; owl:someValuesFrom fis:PutOption ] ) ] ;
  rdfs:label "Putable Bond" ;
  rdfs:comment "Gives the holder the right to force the issuer to repay the bond before the maturity date; also called a retractable bond." .

fis:BulletBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "A straight bond that is neither callable nor putable." .

fis:ConvertibleBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasConversionRight ; owl:someValuesFrom fis:CommonStock ] ) ] ;
  rdfs:subClassOf fis:HybridSecurity ;
  rdfs:label "Convertible Bond" ;
  rdfs:comment "A bond that the holder can convert into a specified number of shares of the issuer's common stock." .

fis:ExchangeableBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
  rdfs:comment "Allows conversion into shares of a corporation other than the issuer." .

fis:PerpetualBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "A bond with no maturity date, also called a perpetuity." .

fis:BearerBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond fis:BearerSecurity ) ] ;
  rdfs:comment "An official certificate issued without a named holder; claimable by whoever possesses it." .
fis:RegisteredBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond fis:RegisteredSecurity ) ] ;
  rdfs:comment "A bond whose ownership is recorded by the issuer or a transfer agent." .
fis:BookEntryBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond fis:BookEntrySecurity ) ] ;
  rdfs:comment "A bond without a paper certificate." .

#################################################################
# ASSET-BACKED FAMILY
#################################################################

fis:UnderlyingAsset a owl:Class ; rdfs:label "Underlying Asset" ;
  rdfs:comment "A cash-flow-producing asset that can back an asset-backed security." .

fis:Mortgage a owl:Class ; rdfs:subClassOf fis:UnderlyingAsset .
fis:AutoLoan a owl:Class ; rdfs:subClassOf fis:UnderlyingAsset .
fis:CreditCardReceivable a owl:Class ; rdfs:subClassOf fis:UnderlyingAsset .
fis:StudentLoan a owl:Class ; rdfs:subClassOf fis:UnderlyingAsset .
fis:HomeEquityLoan a owl:Class ; rdfs:subClassOf fis:Mortgage .
fis:DebtObligation a owl:Class ; rdfs:subClassOf fis:UnderlyingAsset ;
  rdfs:comment "Other bonds or asset-backed securities used as collateral for a CDO." .

fis:AssetBackedSecurity a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:isBackedBy ; owl:someValuesFrom fis:UnderlyingAsset ] ) ] ;
  rdfs:label "Asset-Backed Security" ;
  rdfs:comment "A bond whose interest and principal payments are backed by underlying cash flows from a pool of other assets. Also used, in a narrower sense, specifically for securities backed by consumer loans (distinct from MBS and CDO)." .

fis:MortgageBackedSecurity a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:AssetBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:isBackedBy ; owl:someValuesFrom fis:Mortgage ] ) ] ;
  rdfs:label "Mortgage-Backed Security" .

fis:CollateralizedDebtObligation a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:AssetBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:isBackedBy ; owl:someValuesFrom fis:DebtObligation ] ) ] ;
  rdfs:label "Collateralized Debt Obligation" .

fis:AutoLoanBackedSecurity a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:AssetBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:isBackedBy ; owl:someValuesFrom fis:AutoLoan ] ) ] .

fis:CreditCardBackedSecurity a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:AssetBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:isBackedBy ; owl:someValuesFrom fis:CreditCardReceivable ] ) ] .

fis:StudentLoanBackedSecurity a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:AssetBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:isBackedBy ; owl:someValuesFrom fis:StudentLoan ] ) ] ;
  rdfs:comment "Also called SLABS." .

fis:HomeEquityLoanBackedSecurity a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:AssetBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:isBackedBy ; owl:someValuesFrom fis:HomeEquityLoan ] ) ] .

fis:CoveredBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Backed by cash flows from mortgages or public sector assets, but unlike an asset-backed security, the assets remain on the issuer's balance sheet." .

fis:ResidentialMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:comment "Secured by single-family, one- to four-unit real estate." .
fis:CommercialMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:comment "Secured by commercial and multi-family properties." .

owl:AllDisjointClasses [ owl:members ( fis:ResidentialMortgageBackedSecurity fis:CommercialMortgageBackedSecurity ) ] .

fis:CollateralizedMortgageObligation a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:comment "A pay-through bond; a debt obligation collateralized by the mortgage assets it owns, divided into tranches." .

fis:StrippedMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:comment "Mortgage payments are split into interest-only and principal-only components." .
fis:InterestOnlyStrip a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity .
fis:PrincipalOnlyStrip a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity .

owl:AllDisjointClasses [ owl:members ( fis:InterestOnlyStrip fis:PrincipalOnlyStrip ) ] .

#################################################################
# STOCK / EQUITY FAMILY
#################################################################

fis:Stock a owl:Class ;
  rdfs:subClassOf fis:EquitySecurity ;
  rdfs:label "Stock" ;
  rdfs:comment "Consists of all shares by which ownership of a corporation is divided; synonym: share." .

fis:CommonStock a owl:Class ;
  rdfs:subClassOf fis:Stock ;
  rdfs:comment "Carries voting rights; lowest priority for dividends and liquidation proceeds among shareholders." .

fis:PreferredStock a owl:Class ;
  rdfs:subClassOf fis:Stock ;
  rdfs:subClassOf fis:HybridSecurity ;
  rdfs:label "Preferred Stock" ;
  rdfs:comment "A component of share capital with properties of both equity and debt; senior to common stock but subordinate to bonds in claims; priority on dividends and liquidation." .

owl:AllDisjointClasses [ owl:members ( fis:CommonStock fis:PreferredStock ) ] .

fis:CumulativePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
  rdfs:comment "Unpaid dividends accumulate and must be paid before common-stock dividends may resume." .
fis:NoncumulativePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
  rdfs:comment "Any passed dividend is simply lost." .

owl:AllDisjointClasses [ owl:members ( fis:CumulativePreferredStock fis:NoncumulativePreferredStock ) ] .

fis:ConvertiblePreferredStock a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:PreferredStock
      [ a owl:Restriction ; owl:onProperty fis:hasConversionRight ; owl:someValuesFrom fis:CommonStock ] ) ] ;
  rdfs:label "Convertible Preferred Stock" ;
  rdfs:comment "Preferred stock that includes the ability of the holder to convert into a fixed number of common shares." .

#################################################################
# DEPOSITARY RECEIPTS
#################################################################

fis:DepositaryReceipt a owl:Class ;
  rdfs:subClassOf fis:EquitySecurity ;
  rdfs:comment "A negotiable financial instrument issued by a bank to represent a foreign company's publicly traded securities." .

fis:AmericanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ;
  rdfs:comment "Listed and traded in the United States." .
fis:EuropeanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt .
fis:GlobalDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt .

owl:AllDisjointClasses [ owl:members ( fis:AmericanDepositaryReceipt fis:EuropeanDepositaryReceipt fis:GlobalDepositaryReceipt ) ] .

#################################################################
# WARRANTS
#################################################################

fis:EquityWarrant a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Derivative
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:CommonStock ]
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] ;
  rdfs:subClassOf fis:HybridSecurity ;
  rdfs:label "Equity Warrant" ;
  rdfs:comment "An option issued by the company itself allowing the holder to purchase a specific number of shares at a specified price within a specified time." .

#################################################################
# DERIVATIVE SUBCLASSES (Forward / Future / Option / Swap)
#################################################################

fis:Forward a owl:Class ;
  rdfs:subClassOf fis:Derivative ;
  rdfs:label "Forward" ;
  rdfs:comment "A non-standardized contract between two parties to buy or sell an asset at a specified future time at an amount agreed today." .

fis:Future a owl:Class ;
  rdfs:subClassOf fis:Derivative ;
  rdfs:label "Future" ;
  rdfs:comment "A standardized contract, written by a clearing house that operates an exchange, to buy or sell an asset on a future date at a price specified today." .

fis:Option a owl:Class ;
  rdfs:subClassOf fis:Derivative ;
  rdfs:label "Option" ;
  rdfs:comment "Gives the owner the right, but not the obligation, to buy or sell an underlying asset at a specified strike price on or before a specified date." .

fis:Swap a owl:Class ;
  rdfs:subClassOf fis:Derivative ;
  rdfs:label "Swap" ;
  rdfs:comment "Two counterparties exchange cash flows of one party's financial instrument for those of the other's, computed over a notional principal amount." .

owl:AllDisjointClasses [ owl:members ( fis:Forward fis:Future fis:Option fis:Swap ) ] .

fis:CallOption a owl:Class ;
  rdfs:subClassOf fis:Option ;
  rdfs:comment "The right, but not the obligation, to buy an asset at a fixed price." .
fis:PutOption a owl:Class ;
  rdfs:subClassOf fis:Option ;
  rdfs:comment "The right, but not the obligation, to sell an asset at a fixed price." .

owl:AllDisjointClasses [ owl:members ( fis:CallOption fis:PutOption ) ] .

fis:AmericanOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "May be exercised on any trading day on or before expiration." .
fis:EuropeanOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "May only be exercised on expiry." .

owl:AllDisjointClasses [ owl:members ( fis:AmericanOption fis:EuropeanOption ) ] .

fis:StockOption a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Stock ] ) ] ;
  rdfs:label "Stock Option" .

fis:StockFuture a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Future
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Stock ] ) ] ;
  rdfs:label "Stock Future" ;
  rdfs:comment "A cash-settled futures contract on the value of a stock or stock market index." .

fis:InterestRateSwap a owl:Class ; rdfs:subClassOf fis:Swap ;
  rdfs:comment "Exchange of cash flows representing periodic interest payments, usually fixed for floating." .
fis:CurrencySwap a owl:Class ; rdfs:subClassOf fis:Swap .

fis:CreditDefaultSwap a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Swap
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:DebtSecurity ] ) ] ;
  rdfs:label "Credit Default Swap" ;
  rdfs:comment "The seller compensates the buyer in the event of a loan default or other credit event on a reference loan." .

owl:AllDisjointClasses [ owl:members ( fis:InterestRateSwap fis:CurrencySwap fis:CreditDefaultSwap ) ] .

#################################################################
# FUNDS
#################################################################

fis:InvestmentFund a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:label "Investment Fund" ;
  rdfs:comment "Pools money from many investors to purchase securities; the combined holdings are the fund's portfolio." .

fis:MutualFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Shares purchased from or sold to the issuer at net asset value." .
fis:ExchangeTradedFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Shares trade on national securities exchanges at market prices that may differ from net asset value." .
fis:HedgeFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Pools money from investors with fewer regulatory protections and more flexible, riskier strategies than mutual funds." .
fis:MoneyMarketFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Invests in money market instruments." .
fis:BondFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund .
fis:StockFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund .
fis:IndexFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Passively managed fund that tracks the performance of a market index." .

#################################################################
# MARKETS
#################################################################

fis:FinancialMarket a owl:Class ; rdfs:label "Financial Market" .

fis:PrimaryMarket a owl:Class ; rdfs:subClassOf fis:FinancialMarket ;
  rdfs:comment "The market for new securities, in which the issuer receives the sale proceeds directly." .
fis:SecondaryMarket a owl:Class ; rdfs:subClassOf fis:FinancialMarket ;
  rdfs:comment "The market for already-issued securities trading between investors." .

owl:AllDisjointClasses [ owl:members ( fis:PrimaryMarket fis:SecondaryMarket ) ] .

fis:MoneyMarket a owl:Class ; rdfs:subClassOf fis:FinancialMarket ;
  rdfs:comment "Market for short-term funds with original maturities of one year or less." .
fis:CapitalMarket a owl:Class ; rdfs:subClassOf fis:FinancialMarket ;
  rdfs:comment "Market for longer-term instruments with terms extending beyond one year." .

owl:AllDisjointClasses [ owl:members ( fis:MoneyMarket fis:CapitalMarket ) ] .

fis:StockExchange a owl:Class ; rdfs:subClassOf fis:FinancialMarket ;
  rdfs:comment "An organized and officially recognized market on which securities can be bought and sold." .

#################################################################
# ACCOUNTING CLASSIFICATION (IAS 32 / IFRS 9)
#################################################################

fis:AccountingClassification a owl:Class ;
  rdfs:comment "The IAS 32 classification of a financial instrument's component, determined by the substance of the contractual rights and obligations rather than its legal form." .

fis:IAS32FinancialAsset a owl:Class ; rdfs:subClassOf fis:AccountingClassification ;
  rdfs:comment "Cash; an equity instrument of another entity; a contractual right to receive cash or another financial instrument; or a contractual right to exchange financial instruments under potentially favourable conditions." .

fis:IAS32FinancialLiability a owl:Class ; rdfs:subClassOf fis:AccountingClassification ;
  rdfs:comment "A contractual obligation to deliver cash or another financial asset, or to exchange financial instruments under potentially unfavourable conditions." .

fis:IAS32EquityInstrument a owl:Class ; rdfs:subClassOf fis:AccountingClassification ;
  rdfs:comment "Any contract that evidences a residual interest in the assets of an entity after deducting all of its liabilities. A mandatorily redeemable preference share is classified as a financial liability under this test, even though it is commonly labelled preferred equity -- illustrating that market naming and IAS 32 classification can diverge." .

owl:AllDisjointClasses [ owl:members ( fis:IAS32FinancialLiability fis:IAS32EquityInstrument ) ] .

fis:MeasurementCategory a owl:Class ;
  rdfs:comment "The IFRS 9 subsequent measurement category of a financial asset." .
fis:AmortizedCostMeasurement a owl:Class ; rdfs:subClassOf fis:MeasurementCategory ;
  rdfs:comment "Applies when the asset is held to collect contractual cash flows that are solely payments of principal and interest (SPPI)." .
fis:FVOCIMeasurement a owl:Class ; rdfs:subClassOf fis:MeasurementCategory ;
  rdfs:comment "Fair value through other comprehensive income; held to both collect and sell, and passes SPPI." .
fis:FVTPLMeasurement a owl:Class ; rdfs:subClassOf fis:MeasurementCategory ;
  rdfs:comment "Fair value through profit or loss; default category, including all derivatives." .

owl:AllDisjointClasses [ owl:members ( fis:AmortizedCostMeasurement fis:FVOCIMeasurement fis:FVTPLMeasurement ) ] .

#################################################################
# OBJECT PROPERTIES
#################################################################

fis:hasIssuer a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:label "hasIssuer" ;
  rdfs:domain fis:Security ;
  rdfs:range fis:Issuer ;
  rdfs:comment "The company or other entity issuing the security." .

fis:isIssuerOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasIssuer ;
  rdfs:domain fis:Issuer ;
  rdfs:range fis:Security .

fis:hasUnderlying a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:label "hasUnderlying" ;
  rdfs:domain fis:Derivative ;
  rdfs:range fis:Underlier ;
  rdfs:comment "The item (underlier) on which the value of the derivative depends." .

fis:isUnderlyingOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasUnderlying ;
  rdfs:domain fis:Underlier ;
  rdfs:range fis:Derivative .

fis:hasConversionRight a owl:ObjectProperty ;
  rdfs:label "hasConversionRight" ;
  rdfs:domain fis:Security ;
  rdfs:range fis:CommonStock ;
  rdfs:comment "Relates a convertible security to the common stock into which it may be converted." .

fis:hasEmbeddedOption a owl:ObjectProperty ;
  rdfs:label "hasEmbeddedOption" ;
  rdfs:domain fis:Bond ;
  rdfs:range fis:Option ;
  rdfs:comment "Relates a bond to an option-like feature granted to the holder or issuer, such as a call or put provision." .

fis:isBackedBy a owl:ObjectProperty ;
  rdfs:label "isBackedBy" ;
  rdfs:domain fis:AssetBackedSecurity ;
  rdfs:range fis:UnderlyingAsset ;
  rdfs:comment "Relates an asset-backed security to the pool of underlying assets whose cash flows back it." .

fis:hasCreditRating a owl:ObjectProperty ;
  rdfs:label "hasCreditRating" ;
  rdfs:domain fis:Security ;
  rdfs:range fis:CreditRating .

fis:isTradedIn a owl:ObjectProperty ;
  rdfs:label "isTradedIn" ;
  rdfs:domain fis:Security ;
  rdfs:range fis:FinancialMarket .

fis:hasAccountingClassification a owl:ObjectProperty ;
  rdfs:label "hasAccountingClassification" ;
  rdfs:domain fis:FinancialInstrument ;
  rdfs:range fis:AccountingClassification .

fis:hasMeasurementCategory a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:label "hasMeasurementCategory" ;
  rdfs:domain fis:IAS32FinancialAsset ;
  rdfs:range fis:MeasurementCategory .

#################################################################
# DATATYPE PROPERTIES
#################################################################

fis:hasMaturityDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:label "hasMaturityDate" ;
  rdfs:domain fis:Bond ;
  rdfs:range xsd:date ;
  rdfs:comment "The date on which the issuer is obligated to repay the nominal amount." .

fis:hasFaceValue a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:label "hasFaceValue" ;
  rdfs:domain fis:Bond ;
  rdfs:range xsd:decimal ;
  rdfs:comment "Nominal, principal, par, or face amount on which the issuer pays interest and which is repaid at maturity." .

fis:hasCouponRate a owl:DatatypeProperty ;
  rdfs:label "hasCouponRate" ;
  rdfs:domain fis:Bond ;
  rdfs:range xsd:decimal ;
  rdfs:comment "The interest rate that the issuer pays to the holder." .

fis:hasYieldToMaturity a owl:DatatypeProperty ;
  rdfs:domain fis:Bond ;
  rdfs:range xsd:decimal .

fis:hasCurrentYield a owl:DatatypeProperty ;
  rdfs:domain fis:Bond ;
  rdfs:range xsd:decimal .

fis:hasDividendRate a owl:DatatypeProperty ;
  rdfs:domain fis:PreferredStock ;
  rdfs:range xsd:decimal .

fis:hasStrikePrice a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:label "hasStrikePrice" ;
  rdfs:domain fis:Option ;
  rdfs:range xsd:decimal ;
  rdfs:comment "The price at which the underlying transaction will occur upon exercise." .

fis:hasExpirationDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ;
  rdfs:range xsd:date .

fis:hasPremium a owl:DatatypeProperty ;
  rdfs:domain fis:Option ;
  rdfs:range xsd:decimal .

fis:hasNotionalAmount a owl:DatatypeProperty ;
  rdfs:domain fis:Swap ;
  rdfs:range xsd:decimal ;
  rdfs:comment "The amount used to calculate swap cash flows; generally not exchanged between counterparties." .

fis:hasDeliveryDate a owl:DatatypeProperty ;
  rdfs:domain fis:Derivative ;
  rdfs:range xsd:date ;
  rdfs:comment "The future date by which the purchase/sale act specified in a derivative contract must take place." .

fis:hasDeliveryPrice a owl:DatatypeProperty ;
  rdfs:domain fis:Derivative ;
  rdfs:range xsd:decimal ;
  rdfs:comment "The price agreed upon today at which the future transaction under a derivative contract must take place." .
